// Validates the form, works out whether the upload is an image or a video and names the file for CEKIVA.
const f = $json || {};
const input = $input.first();
const caption = String(f['Caption'] || '').trim();
const clientId = String(f['Client workspace ID'] || '').trim();
const picked = Array.isArray(f['Networks']) ? f['Networks'] : (f['Networks'] ? [f['Networks']] : []);
if (!caption) throw new Error('Caption is required.');
if (clientId && !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(clientId)) throw new Error('Client workspace ID must be a UUID (see GET https://cekiva.com/api/v1/clients).');

const NETWORKS = { 'Facebook Page': 'facebook_page', 'Instagram': 'instagram', 'LinkedIn': 'linkedin', 'Threads': 'threads', 'Bluesky': 'bluesky',
                   'TikTok (video only)': 'tiktok', 'YouTube (video only)': 'youtube' }; // X/Twitter is not here: CEKIVA retired that channel
const platforms = [...new Set(picked.map((x) => NETWORKS[x]).filter(Boolean))];
if (!platforms.length) throw new Error('Pick at least one network.');

const bin = input.binary && input.binary['Upload'];
if (!bin) throw new Error('Please upload an image or a video.');
const mime = String(bin.mimeType || '').toLowerCase();
const EXT = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif', 'video/mp4': 'mp4', 'video/quicktime': 'mov', 'video/webm': 'webm' };
if (!EXT[mime]) throw new Error('Unsupported file type (' + (mime || 'unknown') + '). Use JPG, PNG, WebP, GIF, MP4, MOV or WebM.');
const kind = mime.startsWith('video/') ? 'video' : 'image';
// CEKIVA reads the type from the file name (and TikTok only takes .mp4 / .mov / .webm): name the file explicitly.
bin.fileName = 'upload.' + EXT[mime];
bin.mimeType = mime;

const skipped = [];
const usable = platforms.filter((p) => {
  if (kind === 'image' && (p === 'tiktok' || p === 'youtube')) { skipped.push({ platform: p, reason: p + ' needs a video, you uploaded an image' }); return false; }
  return true;
});
if (!usable.length) throw new Error('Nothing to publish: ' + skipped.map((s) => s.reason).join('; '));
return [{ json: { kind, caption, platforms: usable, skipped, clientId }, binary: { Upload: bin } }];

// CEKIVA publishing: one POST /v1/posts per network with the uploaded media (hosted by CEKIVA).
// X/Twitter is not here on purpose: CEKIVA retired that channel.
const CONFIG = {
  PUBLISH_NOW: true,  // true = publish right away; false = publish at SCHEDULED_AT
  SCHEDULED_AT: '',   // ISO 8601 with a time zone, e.g. 2026-12-01T09:00:00Z (used only when PUBLISH_NOW is false)
};
const prep = $('Prepare media').first().json;
const up = $input.first().json || {};
if (!up.url) throw new Error('CEKIVA did not return a media url.');
const scheduleAt = !CONFIG.PUBLISH_NOW && CONFIG.SCHEDULED_AT ? CONFIG.SCHEDULED_AT : null;
const items = prep.platforms.map((platform) => {
  // The body of POST /v1/posts exactly as the CEKIVA API expects it.
  const request = { platforms: [platform], content: prep.caption, image_url: up.url, media_urls: [up.url],
                    scheduled_for: scheduleAt || new Date().toISOString(), publish_now: !scheduleAt };
  if (prep.clientId) request.client_id = prep.clientId;
  return { json: { platform, request } };
});
items[0].json.skipped = prep.skipped; // carried to the summary
return items;

// One uniform result row per network, and a short text summary for the form's ending page.
const sent = $('Build CEKIVA posts').all();
const skipped = (sent[0] && sent[0].json.skipped) || [];
const rows = $input.all().map((item, i) => {
  const r = item.json;
  const platform = sent[i] ? sent[i].json.platform : 'unknown';
  const body = r.body;
  const post = Array.isArray(body) ? body[0] : null;
  const err = body && !Array.isArray(body) && body.error && typeof body.error === 'object' ? body.error : null;
  const status = Number(r.statusCode) || null;
  const ok = status !== null && status >= 200 && status < 300 && !!post;
  return {
    platform,
    result: ok ? 'Success' : 'Error',
    http_status: status,
    post_id: post ? post.id : null,
    post_status: post ? post.status : null,
    credits_charged: post ? post.credits_charged : null,
    error_code: err ? err.code : (r.error ? 'CEKIVA_UNREACHABLE' : null),
    error_message: err ? err.message : (r.error ? String(r.error.message || r.error).slice(0, 200) : (ok ? null : 'Unexpected response')),
    hint: err ? err.hint : null,
  };
});
const lines = rows.map((x) => (x.result === 'Success' ? '✅ ' + x.platform + ' (' + x.post_status + ')' : '❌ ' + x.platform + ': ' + (x.error_code || '') + ' ' + (x.error_message || '')));
for (const s of skipped) lines.push('⏭️ ' + s.platform + ' skipped: ' + s.reason);
return [{ json: { rows, skipped, summary: lines.join('\n') } }];
